import{z as p,x as E,o as n,c as B,q as o,j as d,D as t,d as r,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"树上倍增与差分","description":"","frontmatter":{"title":"树上倍增与差分","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tree-binary-lifting.md","filePath":"cs/tree-binary-lifting.md","lastUpdated":1791413859000}'),A={name:"cs/tree-binary-lifting.md"};function c(D,a,u,m,f,h){const l=E("Mermaid");return n(),B("div",null,[a[2]||(a[2]=o('<h1 id="树上倍增与差分" tabindex="-1">树上倍增与差分 <a class="header-anchor" href="#树上倍增与差分" aria-label="Permalink to &quot;树上倍增与差分&quot;">​</a></h1><div class="epigraph"><p>$2^k$ 祖先表既答 LCA，也把路径拆成 $O(\\log n)$ 段；边上或点上的增减，用差分在子树和里一次 DFS 还原。</p><footer>—— 据 CLRS 第 21、22 章的倍增与前缀思想；竞赛与教材中的树上差分整理</footer></div><p>上一课<a href="/cs/lca">最近公共祖先</a>给出 <code>lca(u,v)</code> 与倍增表 <code>fa[k][u]</code>。本课不重写对齐深度再跳。缺口是<strong>同一张表的其余用法</strong>：路径信息（最小边权、和）沿倍增合并；以及把「路径 \\(+d\\)」变成点上差分，再 DFS 子树还原。后课重链剖分把路径变成序列上的线段树，本课先用倍增与差分做静态。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态有根树。路径 \\(u\\)–\\(v\\) 拆成 \\(u\\to lca\\) 与 \\(v\\to lca\\)。若只要路径边权和：预处理到根的前缀和，\\(ans=pre[u]+pre[v]-2\\cdot pre[lca]\\)（边权挂在子端）。点权类似，注意 \\(lca\\) 是否算两次。缺口是这套前缀，不是再证 LCA。</p><p>倍增聚合：<code>min[k][u]</code> 为 \\(u\\) 上跳 \\(2^k\\) 步路径上的边权 \\(\\min\\)。查询时与跳父同步合并。适合可结合、可重复（幂等）或注意重叠的运算。不可结合的要换剖分。</p><p>树上差分：路径 \\(u\\)–\\(v\\) 上每点 \\(+d\\)。令 \\(a[u]+=d\\)，\\(a[v]+=d\\)，\\(a[lca]-=d\\)，\\(a[parent[lca]]-=d\\)（点差分；边差分公式略改）。再从叶子向根累加子树，\\(a\\) 变成真实点值。一次 DFS \\(O(n)\\) 答完所有修改后的查询（离线）。</p><h3 id="差分不是线段树" tabindex="-1">差分不是线段树 <a class="header-anchor" href="#差分不是线段树" aria-label="Permalink to &quot;差分不是线段树&quot;">​</a></h3><p>序列差分把区间加变成两点；树上同构，两点换成路径两端与 LCA。不要对每次询问 \\(O(n)\\) 走路径。动态反复改结构用重链或 LCT，本课静态。</p><p><span class="marginnote">倍增与整数的二进制分解同类，快速幂课会写 \\(a^n\\)。树上差分是前缀和的树版本。无单独经典论文名时，CLRS 的前缀与并查集思想足够支撑。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预处理深度、父、<code>fa[k]</code>、可选 <code>min[k]</code>、\\(O(n\\log n)\\)。路径和用前缀。离线路径加：差分数组 + 子树和。</p>',12)),(n(),d(s,null,{default:t(()=>[i(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FA%5B%22fa%5Bk%5D%5Bu%5D%20%E5%80%8D%E5%A2%9E%5D%20--%3E%20LCA%5BLCA%20%2F%20%E8%B7%AF%E5%BE%84%E6%AE%B5%22%5D%0A%20%20PRE%5B%22%E5%88%B0%E6%A0%B9%E5%89%8D%E7%BC%80%22%5D%20--%3E%20SUM%5B%22%E8%B7%AF%E5%BE%84%E5%92%8C%22%5D%0A%20%20DIFF%5B%22%E8%B7%AF%E5%BE%84%E5%B7%AE%E5%88%86%22%5D%20--%3E%20DFS%5B%22DFS%20%E8%BF%98%E5%8E%9F%E7%82%B9%E5%80%BC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"边权与点权选一种挂法，全程一致。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"二进制跳转覆盖任意深度差，段数 \\(O(\\log n)\\)。差分正确性：除路径外，每点被加减抵消；LCA 与父的修正避免把 LCA 上方加进去。子树求和等价于从根到该点的差分前缀——与序列 \\(b[i]=a[i]-a[i-1]\\) 同一线性关系。",-1)),a[6]||(a[6]=e("p",null,"四个符号位怎么落进正确的点，用一次求和看清：",-1)),(n(),d(s,null,{default:t(()=>[i(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22a%5Bu%5D%20%2B%3D%20d%5D%20--%3E%20L%5Ba%5Blca%5D%20-%3D%20d%22%5D%0A%20%20V%5B%22a%5Bv%5D%20%2B%3D%20d%22%5D%20--%3E%20L%0A%20%20L%20--%3E%20P%5B%22a%5Bparent%5Blca%5D%5D%20-%3D%20d%22%5D%0A%20%20P%20--%3E%20S%5B%22%E5%AF%B9%E6%AF%8F%E4%B8%AA%E7%82%B9%E5%81%9A%E5%AD%90%E6%A0%91%E6%B1%82%E5%92%8C%22%5D%0A%20%20S%20--%3E%20ON%5B%22%E8%B7%AF%E5%BE%84%E4%B8%8A%E7%9A%84%E7%82%B9%20%3D%20d%22%5D%0A%20%20S%20--%3E%20OFF%5B%22%E8%B7%AF%E5%BE%84%E5%A4%96%E7%9A%84%E7%82%B9%20%3D%200%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">直觉类比：差分点像「在 \\(u\\) 和 \\(v\\) 各插一面 +d 的旗，再在 LCA 与它的父节点各拔一次」。子树求和时，只有根到该点的路径恰好穿过目标路径的点才能收齐 \\(+d+d-d-d\\) 中正确的组合——路径上正好剩一个 \\(d\\)，路径外正负全抵消。</span></p><p><span class="marginnote">常见误区：初学者容易以为「路径 \\(+d\\)」要沿 \\(u\\to lca\\to v\\) 逐点修改。实际只改 4 个点，最后一次 DFS 还原；\\(m\\) 次修改加 \\(n\\) 个点的总代价是 \\(O(m+n)\\)，而不是逐路径的 \\(O(m\\cdot depth)\\)。代价被挪到了「读答案之前」的一次性遍历。</span></p><p>不要在有向有环图上做这套前缀：唯一路径是树的性质。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写重链、不写点分治、不写动态边。子树修改（整棵子树 \\(+d\\)）是 DFS 序差分，比路径更简单，点名即可。后课默认：静态路径和/最值可用倍增或前缀；路径加用树上差分。下一课把路径切成 \\(O(\\log n)\\) 条重链，接上序列数据结构。</p><p><span class="marginnote">术语翻译：「子树修改用 DFS 序差分」就是把每个点的进出栈时刻编号，让整棵子树对应一段<strong>连续区间</strong>——树问题随之塌缩成最普通的序列区间加，比路径差分还少扣 LCA 那两个修正点。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>倍增表既跳祖先也聚合路径。</li><li>路径和用到根前缀与 LCA；路径修改用差分 + DFS。</li><li>静态树；动态结构后课。</li><li>出处：倍增与前缀为算法课标准技法；LCA 见 Tarjan, 1979。</li></ul>',8))])}const C=p(A,[["render",c]]);export{S as __pageData,C as default};
